from pwn import remote

def test_input(input_strings):
    results = {}

    with remote('rev.chal.csaw.io', 5000) as conn:
        for input_data in input_strings:
            conn.recvuntil(b'input?')  # wait for server to prompt
            conn.sendline(input_data.encode())  # send test input
            response = conn.recvline(timeout=5).decode().strip()  # get response
            results[input_data] = response

    return results

if __name__ == "__main__":
    inputs = [
        "AAAAA", "BBBBB", "CCCCC",   # Repeated character inputs
        "12345", "ABCDE", "00000",   # Patterned inputs
        "!!!!!", "@@@@@", "#####",   # Non-alphanumeric inputs
    ]

    results = test_input(inputs)

    for key, value in results.items():
        print(f"Input: {key}, Response: {value}")

from pwn import *

def interact_with_server(server, port, inputs):
    try:
        conn = remote(server, port)
        responses = {}

        for input_data in inputs:
            print(f"Sending input: {input_data}")
            conn.sendline(input_data)
            response = conn.recvline(timeout=5).decode(errors='ignore')
            responses[input_data] = response

        conn.close()
        return responses

    except Exception as e:
        return str(e)

if __name__ == "__main__":
    server = "rev.chal.csaw.io"
    port = 5000
    inputs = ["MAGIC123456", "MAGIC98765", "MAGICFLAG1"]

    responses = interact_with_server(server, port, inputs)

    with open("/home/ctfplayer/ctf_files/server_responses.txt", "w") as f:
        for input_data, response in responses.items():
            f.write(f"Input: {input_data}\nResponse: {response}\n\n")

